/**
 * Emits typed `defineEvents` modules from the channel IR — the events
 * counterpart of `emitter.ts`. Generated files use the same hand-written
 * style (`defineEvents` / `subscribe` / `publish` / `P`) so they stay
 * readable, diffable and editable.
 */

import type { ChannelGroupIR, ChannelIR, EventsIR } from './model.js';
import type { ParamIR, SchemaIR } from './openapi.js';
import {
  clamp,
  emitKind,
  escapeComment,
  formatArgs,
  schemaConstraintArgs,
} from './emitter.js';
import type { EmittedFile, EmitOptions } from './emitter.js';

export function emitEvents(ir: EventsIR, options: EmitOptions = {}): EmittedFile[] {
  const importFrom = options.importFrom ?? 'contractful-ts';
  const files: EmittedFile[] = [];
  const indexExports: { constName: string; file: string }[] = [];

  for (const group of ir.groups) {
    if (group.channels.length === 0) continue;

    const maxPerFile = options.maxPerFile ?? 0;
    const chunks =
      maxPerFile > 0 ? chunk(group.channels, maxPerFile) : [group.channels];

    chunks.forEach((channels, i) => {
      const multi = chunks.length > 1;
      const suffix = multi ? `-part-${i + 1}` : '';
      const constName = group.constName + (multi ? `Part${i + 1}` : '');
      const fileName = group.fileName.replace(/\.ts$/, `${suffix}.ts`);

      files.push({
        path: fileName,
        content: emitEventsFile(ir, group.name, constName, channels, importFrom, options),
      });
      indexExports.push({ constName, file: fileName.replace(/\.ts$/, '') });
    });
  }

  if ((options.emitIndex ?? true) && indexExports.length > 0) {
    const metadata = emitEventsMetadata(ir.title, options);
    // One merged alias map per namespace (single source of truth for
    // string-based subscriptions across every group).
    const aliases = ir.groups.flatMap((group) =>
      group.channels.filter((c) => c.eventAlias).map((c) => [c.eventAlias!, c.topic] as const),
    );
    files.push({
      path: 'index.ts',
      content: [
        `// Auto-generated by contractful-gen from ${originLabel(options.specOrigin)} — DO NOT EDIT.`,
        ...indexExports.map((entry) => `export * from './${entry.file}.js';`),
        '',
        ...(aliases.length > 0
          ? [
              '/** Normalized event names → wire topics (`raw.subscribe(EVENT_NAMES.x, ...)`). */',
              'export const EVENT_NAMES = {',
              ...aliases.map(([alias, topic]) => `  ${JSON.stringify(alias)}: ${JSON.stringify(topic)},`),
              '} as const;',
              '',
            ]
          : []),
        ...(metadata ? [metadata, ''] : []),
      ].join('\n'),
    });
  }

  return files;
}

/** Renders the deterministic `CLIENT_METADATA` block. */
function emitEventsMetadata(title: string, options: EmitOptions): string | undefined {
  if (!options.sourceHash && !options.generatorVersion) return undefined;
  const lines: string[] = ['export const CLIENT_METADATA = {'];
  lines.push(`  generator: 'contractful-ts',`);
  if (options.generatorVersion) lines.push(`  generatorVersion: ${JSON.stringify(options.generatorVersion)},`);
  lines.push(`  api: ${JSON.stringify(title)},`);
  if (options.specOrigin) lines.push(`  sources: [{ file: ${JSON.stringify(options.specOrigin)}, hash: ${JSON.stringify(options.sourceHash ?? '')} }],`);
  lines.push('} as const;');
  return lines.join('\n');
}

function emitEventsFile(
  ir: EventsIR,
  groupName: string,
  constName: string,
  channels: ChannelIR[],
  importFrom: string,
  options: EmitOptions,
): string {
  const lines: string[] = [];
  lines.push(`// Auto-generated by contractful-gen from ${originLabel(options.specOrigin)} — DO NOT EDIT.`);
  lines.push(`// Events: ${ir.title}${ir.version ? ` (${ir.version})` : ''} · group: ${groupName}`);
  lines.push(`// Incoming messages are gated open-world; outgoing messages are validated closed-world.`);
  lines.push('');

  // Message-type declarations for multi-message (envelope) channels.
  for (const channel of channels) {
    emitMessageTypeDeclarations(lines, constName, channel);
  }

  lines.push(`import { defineEvents, subscribe, publish, P } from ${JSON.stringify(importFrom)};`);
  lines.push('');
  lines.push(`export const ${constName} = defineEvents({`);
  lines.push(`  name: ${JSON.stringify(`${ir.title} · ${groupName}`)},`);
  lines.push(`  url: ${JSON.stringify(ir.url)},`);
  lines.push('  channels: {');
  for (const channel of channels) {
    emitChannel(lines, constName, channel);
  }
  lines.push('  },');
  lines.push('});');
  lines.push('');

  return lines.join('\n');
}

/** Emits per-variant interfaces + a union for multi-message channels. */
function emitMessageTypeDeclarations(lines: string[], constName: string, channel: ChannelIR): void {
  if (!channel.messages || channel.messages.length < 2) return;
  const typePrefix = toPascal(constName);
  const unionName = `${typePrefix}${toPascal(channel.name)}Message`;
  for (const message of channel.messages) {
    const typeName = `${typePrefix}${toPascal(message.name)}`;
    if (message.description) {
      lines.push(`/** ${escapeComment(clamp(message.description))} */`);
    }
    lines.push(`export interface ${typeName} ${renderObjectType(message.fields)}`);
    lines.push('');
  }
  lines.push(`/** Union of the messages carried on ${JSON.stringify(channel.topic)}. */`);
  lines.push(`export type ${unionName} = ${channel.messages
    .map((message) => `${toPascal(constName)}${toPascal(message.name)}`)
    .join(' | ')};`);
  lines.push('');
}

/** Renders a TS object literal type from field IR (open-world: extra fields allowed). */
function renderObjectType(fields: ParamIR[]): string {
  if (fields.length === 0) return '{ [key: string]: unknown }';
  const body = fields
    .map((field) => `  ${field.tsName}${field.required ? '' : '?'}: ${tsTypeOf(field.schema)};`)
    .join('\n');
  return `{\n${body}\n}`;
}

/** Maps a schema IR onto a TypeScript type expression. */
function tsTypeOf(schema: SchemaIR): string {
  if (schema.enumValues && schema.enumValues.length > 0) {
    return schema.enumValues.map((v) => JSON.stringify(v)).join(' | ');
  }
  switch (schema.type) {
    case 'integer':
    case 'number':
      return 'number';
    case 'boolean':
      return 'boolean';
    case 'array':
      return `Array<${schema.items ? tsTypeOf(schema.items) : 'unknown'}>`;
    case 'object':
      return 'Record<string, unknown>';
    case 'string':
    default:
      return 'string';
  }
}

function toPascal(name: string): string {
  return name
    .split(/[^a-zA-Z0-9]+/)
    .filter(Boolean)
    .map((segment) => segment[0]!.toUpperCase() + segment.slice(1))
    .join('');
}

function emitChannel(lines: string[], constName: string, channel: ChannelIR): void {
  const factory = channel.direction === 'in' ? 'subscribe' : 'publish';
  const doc = channel.description ? `/** ${escapeComment(clamp(channel.description))} */\n    ` : '';

  // Multi-message channels subscribe with a generated message union.
  if (channel.messages && channel.messages.length >= 2) {
    const unionName = `${toPascal(constName)}${toPascal(channel.name)}Message`;
    lines.push(
      `    ${doc}${channel.name}: ${factory}<${unionName}>(${JSON.stringify(channel.topic)}),`,
    );
    return;
  }

  const hasParams = channel.params.length > 0;
  const hasFields = channel.fields.length > 0;
  if (!hasParams && !hasFields) {
    lines.push(`    ${doc}${channel.name}: ${factory}(${JSON.stringify(channel.topic)}),`);
    return;
  }

  lines.push(`    ${doc}${channel.name}: ${factory}(${JSON.stringify(channel.topic)}, {`);
  if (hasParams) {
    lines.push('      params: {');
    for (const param of channel.params) emitField(lines, param);
    lines.push('      },');
  }
  if (hasFields) {
    lines.push('      fields: {');
    for (const field of channel.fields) emitField(lines, field);
    lines.push('      },');
  }
  lines.push('    }),');
}

function emitField(lines: string[], param: ParamIR): void {
  const args: string[] = [];
  if (param.required) args.push('required: true');
  if (param.tsName !== param.wireName) args.push(`as: ${JSON.stringify(param.wireName)}`);
  args.push(...schemaConstraintArgs(param.schema));
  const describe = param.schema.description ?? param.description;
  if (describe) args.push(`describe: ${JSON.stringify(clamp(describe))}`);
  lines.push(`        ${param.tsName}: P.${emitKind(param.schema)}(${formatArgs(args)}),`);
}

function chunk<T>(items: T[], size: number): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

function originLabel(origin?: string): string {
  return origin ?? 'AsyncAPI spec';
}
